h,w=13,23
G=[[2]*w for _ in range(h)]
seeds={8:[(2,14),(3,15)],7:[(2,17),(3,16)],5:[(4,15),(5,14)],3:[(4,16),(5,17)]}
for color,pts in seeds.items():
 for r,c in pts:
  # trace both ways along diagonal matching pair slope (dr,dc)
  dr=1 if (pts[1][0]-pts[0][0])*(pts[1][1]-pts[0][1])>0 else 1
  dc=1 if pts[1][1]>pts[0][1] else -1
  for t in range(-30,31):
   rr=r+dr*t; cc=c+dc*t
   if 0<=rr<h and 0<=cc<w:
    if G[rr][cc] not in (2,color): print('collision',rr,cc,color,G[rr][cc])
    G[rr][cc]=color
print('\n'.join(' '.join(map(str,row)) for row in G))
